SC_ACT.scLsView = t => { const d = scD(), l = d.ls.find(x => x.id === t.dataset.k); if (!l) return; const N = d.notes.filter(n => n.lid === l.id && n.state === 'Approved'); modal(`${l.no} v${l.ver} · ${esc(l.title)}`, `<p class="small">${esc(l.ay)} · ${esc(l.board)} · ${esc(l.cls)} · ${esc(l.subject)} · ${esc(l.chapter)} · lesson ${l.order} · ${l.steps.reduce((a, s) => a + (+s.mins || 0), 0)} min · <b>${esc(l.state)}</b> · by ${esc(l.by)}</p><ol>${l.steps.map(s => `<li><b>${esc(s.name)}</b> <span class="small muted">${s.mins} min</span><br>${esc(s.text) || '<span class="muted">—</span>'}${(s.ct || []).length ? `<br><span class="small">${s.ct.map(id => { const c = d.ct.find(x => x.id === id); return c ? `${esc(c.type)}: ${esc(c.title)}` : ''; }).filter(Boolean).join(' · ')}</span>` : ''}</li>`).join('')}</ol>${N.length ? `<h4>Approved teacher notes</h4>${N.map(n => `<p class="small"><b>${esc(n.by)}</b> (${esc((acBr(n.bid) || {}).name || '')}): ${esc(n.text)}${n.file ? ' · ' + esc(n.file) : ''}</p>`).join('')}` : ''}${l.note ? `<div class="note">Returned: ${esc(l.note)}</div>` : ''}`, scFlowBtns(l, 'ls') + ' <button class="btn" data-act="closeModal">Close</button>', true); };
/* ---- teacher notes ---- */
SC_ACT.scNoteForm = t => { const l = scD().ls.find(x => x.id === t.dataset.k); if (!l) return; modal('Add a local note to ' + esc(l.title), `<p class="small">Centrally approved content cannot be changed. Your note or supplementary material appears with the lesson at your branch once the Principal or Academic Coordinator approves it.</p>${pcFld('Note (at least 10 characters)', '<textarea id="sn_t" rows="3"></textarea>')}${pcFld('Supplementary file name (optional)', '<input id="sn_f">')}`, `<button class="btn pri" data-act="scNoteOk0" data-k="${l.id}">Send for approval</button>`); };
SC_ACT.scNoteOk0 = async t => { const l = scD().ls.find(x => x.id === t.dataset.k); if (!l) return; const text = (v('sn_t') || '').trim(), file = (v('sn_f') || '').trim(); if (text.length < 10) return toast('Write the note (at least 10 characters).', 'bad'); const me = acMe(), bid = me ? me.bid : acBidSel().bid; const d = Store.clone(scD()); d.notes.unshift({ id: scId('SN'), lid: l.id, bid, text, file, state: 'Pending', by: App.user.name, at: nowIso() }); scLog(d, 'Teacher note submitted', { new: `${l.no} · ${text.slice(0, 60)}` }); await scSave(d); closeModal(); toast('Sent for approval.'); rerender(); };
