  const LS = a ? scLessonsFor(cls, subject) : [], chapters = [...new Set(LS.map(l => l.chapter))], chapter = chapters.includes(u.chapter) ? u.chapter : chapters[0], L2 = LS.filter(l => l.chapter === chapter), lesson = L2.find(l => l.id === u.lid) || L2[0];
