  const picker = `<div class="ctrls" style="gap:12px">${sel('ay', [[CUR_AY, CUR_AY]], CUR_AY, 'Academic year')}${sel('bid', bids.map(b => [b, (acBr(b) || {}).name]), bid, 'Branch')}${sel('cls', classes.map(c => [c, c]), cls, 'Grade')}${sel('sec', secs.map(s => [s, s]), sec, 'Section')}${sel('subject', subs.map(s => [s, s]), subject, 'Subject')}${sel('chapter', chapters.map(c => [c, c]), chapter, 'Chapter')}${sel('lid', L2.map(l => [l.id, `${l.order}. ${l.title}${scLessonDone(l.id, bid, cls, sec) ? ' ✓' : ''}`]), lesson ? lesson.id : '', 'Lesson')}</div>`;
  const tips = lesson ? scD().ct.filter(c => scLive(c) && c.cls === cls && c.subject === subject && c.chapter === lesson.chapter && /Teacher manual|Micro-training/.test(c.type)) : [];
