  const body = picker + (lesson ? `<div class="card" style="padding:16px"><h3 style="margin:0 0 6px">${esc(lesson.title)}</h3><p class="small muted">${esc(lesson.chapter)} · lesson ${lesson.order} · ${lesson.steps.reduce((x, s) => x + (+s.mins || 0), 0)} min · ${lesson.steps.reduce((x, s) => x + (s.ct || []).length, 0)} content items · v${lesson.ver}</p>${tips.length ? `<div class="note"><b>Before you teach:</b> ${tips.map(t => `${esc(t.type)}: ${esc(t.title)}${t.url ? ` (<a href="${esc(t.url)}" target="_blank" rel="noopener">open</a>)` : ''}`).join(' · ')}</div>` : ''}<div class="btns" style="margin-top:10px"><button class="btn pri" style="font-size:18px;padding:14px 22px" data-act="tmStart" data-k="${lesson.id}">▶ Present on Smart TV</button><button class="btn" style="font-size:16px;padding:12px 18px" data-act="scLsView" data-k="${lesson.id}">Lesson plan</button><button class="btn" style="font-size:16px;padding:12px 18px" data-act="scNoteForm" data-k="${lesson.id}">Add my note</button></div></div>` : empty('No published lesson for this chapter yet. Lessons come from the Content library.')) +
    table('tm_ss', [{ h: 'Date', t: 'text', k: s => s.date }, { h: 'Lesson', t: 'text', k: s => s.title }, { h: 'Steps done', t: 'text', k: s => `${s.done.length} / 10` }, { h: 'Completed', t: 'html', k: s => pill(s.completed ? 'Yes' : 'Pending portion', s.completed ? 'g' : 'a') }, { h: 'TV', t: 'text', k: s => s.tv ? 'Cast' : 'Tablet only' }, { h: 'Absent', t: 'num', k: s => (s.absent || []).length }, { h: 'Reflection', t: 'text', k: s => s.reflection || '' }], S, { noexp: true, title: 'Recent sessions in this section', empty: 'No sessions yet.' });
