SC_ACT.tmGo = t => { const P = App.ui.tmP; if (!P) return; P.i = +t.dataset.k; P.show = false; rerender(); scSendStep(); };
SC_ACT.tmNext = () => { const P = App.ui.tmP; if (!P) return; if (!P.done.includes(P.i)) P.done.push(P.i); if (P.i < 9) P.i++; P.show = false; rerender(); scSendStep(); };
SC_ACT.tmPrev = () => { const P = App.ui.tmP; if (!P || P.i === 0) return; P.i--; P.show = false; rerender(); scSendStep(); };
SC_ACT.tmSkip = () => { const P = App.ui.tmP; if (!P) return; P.skipped = (P.skipped || []).concat(P.i); if (P.i < 9) P.i++; P.show = false; rerender(); scSendStep(); };
SC_ACT.tmRepeat = () => { const P = App.ui.tmP; if (!P) return; P.repeats = (P.repeats || 0) + 1; P.show = false; rerender(); scSendStep(); };
SC_ACT.tmPause = () => { const P = App.ui.tmP; if (!P) return; P.paused = !P.paused; rerender(); scCast('pause', { on: P.paused }); };
SC_ACT.tmShow = () => { const P = App.ui.tmP; if (!P) return; P.show = !P.show; rerender(); scSendStep(); };
SC_ACT.tmDone = () => { const P = App.ui.tmP; if (!P) return; if (!P.done.includes(P.i)) P.done.push(P.i); else P.done = P.done.filter(x => x !== P.i); rerender(); };
SC_ACT.tmInk = () => { const P = App.ui.tmP; if (!P) return; P.inkOn = !P.inkOn; rerender(); };
SC_ACT.tmClear = () => { const c = document.getElementById('tmInk'); if (c) c.getContext('2d').clearRect(0, 0, c.width, c.height); scCast('clear'); };
SC_ACT.tmTv = () => { const P = App.ui.tmP; if (!P) return; try { if (!SC_TV || SC_TV.closed) { SC_TV = window.open('', 'msea_tv', 'width=1280,height=720'); if (!SC_TV) return toast('The browser blocked the TV window; allow pop-ups and try again.', 'bad'); SC_TV.document.open(); SC_TV.document.write(scTvHtml()); SC_TV.document.close(); } else SC_TV.focus(); P.tv = true; rerender(); setTimeout(scSendStep, 400); } catch (e) { toast('Could not open the TV window: ' + e.message, 'bad'); } };
SC_ACT.tmAbsent = () => { const P = App.ui.tmP; if (!P) return; const R = atRoster(P.bid, P.l.cls, P.sec), today = atD().d[atKey(P.bid, P.l.cls, P.sec, PROC_TODAY)], cur = P.absent || (today ? R.filter(s => today.rec[s.adm] === 'A').map(s => s.adm) : []); modal('Absent in this period', `<p class="small">${today ? 'Pre-filled from today\'s daily attendance.' : 'Daily attendance is not marked yet; mark it under Attendance. This list is for the session record only.'}</p><div style="columns:2">${R.map(s => `<label class="chk" style="display:block"><input type="checkbox" class="tm_ab" value="${esc(s.adm)}" ${cur.includes(s.adm) ? 'checked' : ''}> ${esc(s.name)}</label>`).join('')}</div>`, `<button class="btn pri" data-act="tmAbsentOk">Save</button>`); };
SC_ACT.tmAbsentOk = () => { const P = App.ui.tmP; if (!P) return; P.absent = [...document.querySelectorAll('.tm_ab:checked')].map(i => i.value); closeModal(); rerender(); };
SC_ACT.tmEnd = () => { const P = App.ui.tmP; if (!P) return; modal('End lesson', `<p class="small">${P.done.length} of 10 steps marked done${(P.skipped || []).length ? `, ${P.skipped.length} skipped` : ''}.</p>${pcFld('Lesson completed?', pcSel('te_c', ['Yes – fully taught', 'Partly – pending portion remains', 'No – to be retaught'], P.done.length >= 8 ? 'Yes – fully taught' : 'Partly – pending portion remains'))}${pcFld('Pending portion (if any)', '<input id="te_p">')}${pcFld('Difficulties faced', '<input id="te_d">')}${pcFld('Teacher reflection (at least 10 characters)', '<textarea id="te_r" rows="3"></textarea>')}`, `<button class="btn pri" data-act="tmEndOk">Save session</button>`); };
SC_ACT.tmEndOk = async () => { const P = App.ui.tmP; if (!P) return; const r = (v('te_r') || '').trim(), c = v('te_c'), pend = (v('te_p') || '').trim(); if (r.length < 10) return toast('Write a short reflection (at least 10 characters).', 'bad'); if (c !== 'Yes – fully taught' && pend.length < 3) return toast('Say what is pending.', 'bad'); const d = Store.clone(scD()); const ss = { id: scId('SS'), lid: P.l.id, lno: P.l.no, title: P.l.title, aid: P.a.id, bid: P.bid, cls: P.l.cls, sec: P.sec, subject: P.l.subject, chapter: P.l.chapter, date: PROC_TODAY, startedAt: P.startedAt, endedAt: nowIso(), done: P.done.slice().sort(), skipped: P.skipped || [], repeats: P.repeats || 0, completed: c === 'Yes – fully taught', status: c, pending: pend, difficulties: (v('te_d') || '').trim(), reflection: r, absent: P.absent || [], tv: !!P.tv, ink: !!P.inkUsed, contentUsed: [...new Set(P.l.steps.filter((s, i) => P.done.includes(i)).flatMap(s => s.ct || []))], by: App.user.name, teacher: P.a.teacher, at: nowIso(), sync: Store.mode === 'shared' ? 'Synced' : 'Pending sync' }; d.ss.unshift(ss); scLog(d, 'Lesson session saved', { new: `${ss.lno} · ${ss.cls} ${ss.sec} · ${c}` }, r); await scSave(d); scAud('Lesson session', { new: `${ss.lno} ${ss.cls} ${ss.sec} ${c}` }); try { const a = Store.clone(acD()); a.daily = a.daily || []; if (!a.daily.some(x => x.aid === P.a.id && x.date === PROC_TODAY && x.topic === P.l.title)) { a.daily.push({ id: scId('DP'), aid: P.a.id, bid: P.bid, cls: P.l.cls, sec: P.sec, subject: P.l.subject, teacher: P.a.teacher, date: PROC_TODAY, period: '', topic: P.l.title, method: 'Smart classroom lesson', bloom: [], done: ss.completed ? 'Yes' : 'Partly', note: pend, by: App.user.name, at: nowIso(), auto: true }); await acSave(a); } } catch (e) { } scCast('end'); App.ui.tmP = null; App.ui.tmFull = false; closeModal(); toast('Session saved.'); rerender(); };
/* ink on the tablet stage is mirrored to the TV as normalised strokes */
document.addEventListener('pointerdown', e => { const c = e.target; if (!c || c.id !== 'tmInk' || !(App.ui.tmP || {}).inkOn) return; const P = App.ui.tmP; P.inkUsed = true; const r = c.getBoundingClientRect(); c.width = r.width; c.height = r.height; let last = [e.clientX - r.left, e.clientY - r.top]; const g = c.getContext('2d'); g.strokeStyle = '#facc15'; g.lineWidth = 3; g.lineCap = 'round'; const move = ev => { const p = [ev.clientX - r.left, ev.clientY - r.top]; g.beginPath(); g.moveTo(last[0], last[1]); g.lineTo(p[0], p[1]); g.stroke(); scCast('ink', { x0: last[0] / r.width, y0: last[1] / r.height, x1: p[0] / r.width, y1: p[1] / r.height }); last = p; }; const up = () => { document.removeEventListener('pointermove', move); document.removeEventListener('pointerup', up); }; document.addEventListener('pointermove', move); document.addEventListener('pointerup', up); });
/* ===== classroom devices and sync ===== */
const SC_DEV_TYPES = ['Teacher tablet', 'Smart TV', 'Interactive flat panel', 'Classroom speaker', 'Webcam', 'Document camera'];
PAGES.devices = { title: 'Classroom devices & sync', mod: 'sdev', sf: true, render() {
  const d = scD(), { bid, list } = acBidSel(); if (!list.length) return empty('No branches in your scope for these filters.');
  const tab = pcTab('dv', 'dev'), DV = d.dev.filter(x => x.bid === bid), stale = x => x.lastSeen && x.lastSeen < pcAddDays(PROC_TODAY, -3) + 'T00:00:00', SY = d.sync.filter(x => x.bid === bid).sort((a, b) => b.at.localeCompare(a.at));
  const tabs = pcTabs('dv', [['dev', 'Devices', DV.length], ['sync', 'Sync log', SY.filter(x => x.st === 'Failed').length || ''], ['this', 'This device']], 'dev');
  const bsel = `<div class="ctrls"><label class="fld"><span>Branch</span><select data-act="uiSel" data-k="acBid">${list.map(b => `<option value="${esc(b.id)}" ${b.id === bid ? 'selected' : ''}>${esc(b.name)}</option>`).join('')}</select></label>${can('sdev', 'Add') ? '<button class="btn pri" data-act="dvForm" data-k="">Register device</button>' : ''}</div>`;
  let body = '';
  if (tab === 'dev') { const off = DV.filter(x => x.conn === 'Offline' || stale(x)).length, low = DV.filter(x => x.storagePct >= 90).length, fail = DV.filter(x => x.sync === 'Failed').length; body = bsel + `<div class="kpis k4"><div class="kpi"><span>Devices</span><b>${NUM(DV.length)}</b></div><div class="kpi"><span>Offline or not seen in 3 days</span><b style="color:${off ? '#b91c1c' : 'inherit'}">${NUM(off)}</b></div><div class="kpi"><span>Storage ≥ 90%</span><b style="color:${low ? '#b45309' : 'inherit'}">${NUM(low)}</b></div><div class="kpi"><span>Sync failed</span><b style="color:${fail ? '#b91c1c' : 'inherit'}">${NUM(fail)}</b></div></div>` + table('dv_t', [{ h: 'Device', t: 'text', k: x => `${x.type} · ${x.serial}` }, { h: 'Classroom / teacher', t: 'text', k: x => x.room + (x.emp ? ' · ' + acEmpName(x.emp) : '') }, { h: 'App', t: 'text', k: x => x.appVer || '' }, { h: 'Storage', t: 'text', k: x => x.storagePct != null ? x.storagePct + '%' : '' }, { h: 'Connectivity', t: 'html', k: x => pill(x.conn || 'Unknown', x.conn === 'Online' ? 'g' : 'r') }, { h: 'Last seen', t: 'text', k: x => x.lastSeen ? tsLabel(x.lastSeen) : 'never' }, { h: 'Lessons downloaded', t: 'num', k: x => x.downloads || 0 }, { h: 'Sync', t: 'html', k: x => pill(x.sync || 'Synced', x.sync === 'Failed' ? 'r' : x.sync === 'Pending sync' ? 'a' : 'g') }, { h: '', t: 'html', k: x => can('sdev', 'Add') ? `<button class="btn sm" data-act="dvCheck" data-k="${x.id}">Record check-in</button><button class="btn sm" data-act="dvForm" data-k="${x.id}">Edit</button>` : '' }], DV, { empty: 'No devices registered for this branch.', title: 'Classroom devices' }) + '<div class="note">Devices report health when they check in (connectivity, storage, app version, content downloaded, sync state). In this build the check-in is recorded by IT; a device agent would post it automatically.</div>'; }
  else if (tab === 'sync') body = bsel + table('dv_s', [{ h: 'When', t: 'text', k: x => tsLabel(x.at) }, { h: 'Device', t: 'text', k: x => x.serial }, { h: 'Records', t: 'num', k: x => x.n }, { h: 'Kinds', t: 'text', k: x => x.kinds }, { h: 'Status', t: 'html', k: x => pill(x.st, x.st === 'Failed' ? 'r' : x.st === 'Pending sync' ? 'a' : 'g') }, { h: 'Detail', t: 'text', k: x => x.detail || '' }, { h: '', t: 'html', k: x => x.st === 'Failed' && can('sdev', 'Add') ? `<button class="btn sm" data-act="dvResolve" data-k="${x.id}">Mark resolved</button>` : '' }], SY, { empty: 'No sync events.', title: 'Sync log' }) + '<div class="note">Each record carries a client id, so a retried sync never creates a duplicate.</div>';
  else { const pend = d.ss.filter(s => s.sync === 'Pending sync').length; body = `<div class="kv4"><div><span>Workspace</span><b>${Store.mode === 'shared' ? 'Shared (central)' : 'Local preview'}</b></div><div><span>Network</span><b>${navigator.onLine ? 'Online' : 'Offline'}</b></div><div><span>Lesson sessions pending sync</span><b>${NUM(pend)}</b></div><div><span>Published lessons available</span><b>${NUM(d.ls.filter(scLive).length)}</b></div></div><div class="note">Teaching works from the lessons already loaded in this browser; sessions, attendance and marks saved while offline are kept here and written to the central workspace when it is reachable. Status: <b>${Store.mode === 'shared' ? 'Synced' : 'Pending sync'}</b>.</div>`; }
  return card('Classroom devices & sync', tabs + body, { sub: 'Tablets, Smart TVs and panels per classroom: health, storage, connectivity, content downloads and sync failures.' });
} };
SC_ACT.dvForm = t => { if (!can('sdev', 'Add')) return; const { bid } = acBidSel(), x = scD().dev.find(y => y.id === t.dataset.k) || { type: SC_DEV_TYPES[0], serial: '', room: '', emp: '', appVer: '1.0' }, T = acTeachers(bid); modal(x.id ? 'Edit device' : 'Register device', `<div class="form-grid">${pcFld('Type', pcSel('dv_t', SC_DEV_TYPES, x.type))}${pcFld('Serial / asset tag', `<input id="dv_s" value="${esc(x.serial)}">`)}${pcFld('Classroom', `<input id="dv_r" value="${esc(x.room)}" placeholder="e.g. VI A">`)}${pcFld('Assigned teacher (tablets)', `<select id="dv_e"><option value="">—</option>${T.map(e => `<option value="${e.id}" ${e.id === x.emp ? 'selected' : ''}>${esc(e.name)}</option>`).join('')}</select>`)}${pcFld('App version', `<input id="dv_v" value="${esc(x.appVer || '')}">`)}</div>`, `<button class="btn pri" data-act="dvOk" data-k="${x.id || ''}">Save</button>`); };
SC_ACT.dvOk = async t => { if (!can('sdev', 'Add')) return; const { bid } = acBidSel(), serial = (v('dv_s') || '').trim(), room = (v('dv_r') || '').trim(); if (serial.length < 4) return toast('Enter the serial or asset tag.', 'bad'); if (!room) return toast('Name the classroom.', 'bad'); const d = Store.clone(scD()), x = t.dataset.k ? d.dev.find(y => y.id === t.dataset.k) : null; if (!x && d.dev.some(y => y.serial.toLowerCase() === serial.toLowerCase())) return toast('That serial is already registered.', 'bad'); const o = { type: v('dv_t'), serial, room, emp: v('dv_e') || '', appVer: (v('dv_v') || '').trim() }; if (x) { Object.assign(x, o); scLog(d, 'Device edited', { new: serial }); } else { d.seq.dev++; d.dev.push(Object.assign({ id: scId('DV'), bid, conn: 'Unknown', storagePct: null, lastSeen: '', downloads: 0, sync: 'Synced', by: App.user.name, at: nowIso() }, o)); scLog(d, 'Device registered', { new: `${o.type} · ${serial} · ${room}` }); } await scSave(d); closeModal(); toast('Saved.'); rerender(); };
SC_ACT.dvCheck = t => { const x = scD().dev.find(y => y.id === t.dataset.k); if (!x || !can('sdev', 'Add')) return; modal('Record device check-in · ' + esc(x.serial), `<div class="form-grid">${pcFld('Connectivity', pcSel('dc_c', ['Online', 'Offline'], 'Online'))}${pcFld('Storage used %', `<input id="dc_s" type="number" min="0" max="100" value="${x.storagePct == null ? 40 : x.storagePct}">`)}${pcFld('App version', `<input id="dc_v" value="${esc(x.appVer || '')}">`)}${pcFld('Lessons downloaded for offline use', `<input id="dc_d" type="number" min="0" value="${x.downloads || 0}">`)}${pcFld('Sync result', pcSel('dc_y', ['Synced', 'Pending sync', 'Failed'], 'Synced'))}${pcFld('Records in this sync', `<input id="dc_n" type="number" min="0" value="0">`)}</div>${pcFld('Detail (failure reason, if any)', '<input id="dc_x">')}`, `<button class="btn pri" data-act="dvCheckOk" data-k="${x.id}">Record</button>`); };
SC_ACT.dvCheckOk = async t => { const d = Store.clone(scD()), x = d.dev.find(y => y.id === t.dataset.k); if (!x || !can('sdev', 'Add')) return; const st = v('dc_y'), det = (v('dc_x') || '').trim(); if (st === 'Failed' && det.length < 5) return toast('Say why the sync failed.', 'bad'); x.conn = v('dc_c'); x.storagePct = Math.max(0, Math.min(100, +v('dc_s') || 0)); x.appVer = (v('dc_v') || '').trim(); x.downloads = Math.max(0, +v('dc_d') || 0); x.sync = st; x.lastSeen = nowIso(); d.sync.unshift({ id: scId('SY'), bid: x.bid, dev: x.id, serial: x.serial, n: Math.max(0, +v('dc_n') || 0), kinds: 'attendance, sessions, homework, marks', st, detail: det, at: nowIso() }); scLog(d, 'Device check-in', { new: `${x.serial} · ${x.conn} · ${st}` }, det); await scSave(d); closeModal(); toast('Recorded.'); rerender(); };
SC_ACT.dvResolve = t => { const s = scD().sync.find(y => y.id === t.dataset.k); if (!s || s.st !== 'Failed' || !can('sdev', 'Add')) return; askReason('Mark sync resolved', 'What was done (at least 5 characters).', async why => { if (why.length < 5) return toast('Say what was done.', 'bad'); const d = Store.clone(scD()), x = d.sync.find(y => y.id === s.id); x.st = 'Synced'; x.detail = (x.detail ? x.detail + ' · ' : '') + 'resolved: ' + why; const dv = d.dev.find(y => y.id === x.dev); if (dv) dv.sync = 'Synced'; scLog(d, 'Sync failure resolved', { new: x.serial }, why); await scSave(d); toast('Resolved.'); rerender(); }); };
/* ---- teacher app dashboard block: lessons pending / completed, class strength, assessments, notices, training, alerts, low attendance, remedial ---- */
function scTeacherBlock(me, alloc, secs) {
  const d = scD(), rows = []; alloc.forEach(a => scLessonsFor(a.cls, a.subject).forEach(l => rows.push({ a, l, done: scLessonDone(l.id, a.bid, a.cls, a.sec), last: d.ss.filter(s => s.lid === l.id && s.bid === a.bid && s.sec === a.sec).sort((x, y) => y.at.localeCompare(x.at))[0] })));
  const pend = rows.filter(r => !r.done), done = rows.filter(r => r.done), pct = rows.length ? Math.round(done.length / rows.length * 100) : 0;
  const ex = (typeof exD === 'function' ? exD().papers : []).filter(p => p.date >= PROC_TODAY && alloc.some(a => a.bid === p.bid && a.cls === p.cls && a.subject === p.subject)).sort((a, b) => a.date.localeCompare(b.date)).slice(0, 5);
  const low = []; secs.forEach(s => { const R = atRoster(s.bid, s.cls, s.sec); R.forEach(st => { const H = atOfStudent(st.adm, s.bid, pcAddDays(PROC_TODAY, -30), PROC_TODAY); if (H.length >= 5) { const p = Math.round(H.filter(h => h.st === 'P' || h.st === 'L').length / H.length * 100); if (p < 75) low.push({ name: st.name, adm: st.adm, cls: s.cls + ' ' + s.sec, p }); } }); });
  const nt = (typeof cmD === 'function' ? cmD().nt.filter(n => cmEff(n) === 'Published' && cmFits(n, me)).sort((a, b) => b.pubAt.localeCompare(a.pubAt)) : []).slice(0, 5);
  const tr = (typeof taD === 'function' ? taD().enr.filter(e => e.emp === me.id && e.state !== 'Completed') : []).slice(0, 5);
  const al = typeof eaD === 'function' ? eaD().al.filter(a => eaLive(a) && eaForEmp(a, me)) : [];
  const btn = r => `<button class="btn sm primary" data-act="scTeachGo" data-k="${r.a.bid}|${r.a.cls}|${r.a.sec}|${esc(r.a.subject)}|${r.l.chapter.replace(/\|/g, ' ')}|${r.l.id}">Teach</button>`;
  return `<div class="kpis k4"><div class="kpi"><span>Lessons completed</span><b>${NUM(done.length)} / ${NUM(rows.length)} (${pct}%)</b></div><div class="kpi"><span>Pending lessons</span><b style="color:${pend.length ? '#b45309' : 'inherit'}">${NUM(pend.length)}</b></div><div class="kpi"><span>Students in my sections</span><b>${NUM(secs.reduce((n, s) => n + s.n, 0))}</b></div><div class="kpi"><span>Low attendance (&lt;75%, 30 days)</span><b style="color:${low.length ? '#b91c1c' : 'inherit'}">${NUM(low.length)}</b></div></div>`
    + (al.length ? `<div class="note" style="border-color:#b91c1c"><b>Emergency alert:</b> ${al.map(a => esc(a.type + ': ' + (a.msg || a.text || ''))).join(' · ')}</div>` : '')
    + '<h4>Smart classroom lessons</h4>' + table('taLs', [{ h: 'Class', k: r => r.a.cls + ' ' + r.a.sec, t: 'text' }, { h: 'Subject', k: r => r.a.subject, t: 'text' }, { h: 'Chapter', k: r => r.l.chapter, t: 'text' }, { h: 'Lesson', k: r => `${r.l.order}. ${r.l.title}`, t: 'text', cls: 'wrap' }, { h: 'Status', k: r => r.done ? pill('Completed', 'g') : r.last ? pill('Partly taught', 'a') : pill('Pending', 'n'), t: 'html', x: r => r.done ? 1 : 0 }, { h: 'Last taught', k: r => r.last ? r.last.date : '', t: 'text' }, { h: '', k: r => r.done ? '' : btn(r), t: 'html' }], pend.concat(done), { compact: true, limit: 25, empty: 'No published lessons for your subjects yet.' })
    + '<h4>Upcoming assessments</h4>' + table('taEx', [{ h: 'Date', k: p => p.date, t: 'text' }, { h: 'Class', k: p => p.cls, t: 'text' }, { h: 'Subject', k: p => p.subject, t: 'text' }, { h: 'Exam', k: p => p.exam || p.name || p.title || '', t: 'text' }], ex, { compact: true, empty: 'None scheduled.' })
    + '<h4>Low attendance in my sections</h4>' + table('taLow', [{ h: 'Student', k: r => `${r.name} (${r.adm})`, t: 'text' }, { h: 'Class', k: r => r.cls, t: 'text' }, { h: 'Present %', k: r => r.p, t: 'num' }], low.sort((a, b) => a.p - b.p), { compact: true, limit: 15, empty: 'No one below 75% in the last 30 days.' })
    + (nt.length ? '<h4>Notices</h4>' + table('taNt', [{ h: 'Date', k: n => n.date || n.at || '', t: 'text' }, { h: 'Notice', k: n => n.title || n.subject || '', t: 'text', cls: 'wrap' }], nt.map(n => ({ date: (n.pubAt || '').slice(0, 10), title: n.title })), { compact: true, noexp: true }) : '')
    + (tr.length ? '<h4>Training to complete</h4>' + table('taTr', [{ h: 'Course', k: c => c.title, t: 'text', cls: 'wrap' }, { h: 'Progress', k: c => `${(c.done || []).length} / ${c.nl} lessons · ${c.state}`, t: 'text' }], tr, { compact: true, noexp: true }) : '');
}
SC_ACT.scTeachGo = t => { const [bid, cls, sec, subject, chapter, lid] = t.dataset.k.split('|'); App.ui.tm = { bid, cls, sec, subject, chapter, lid }; go('teach'); };
